import{z as B,x as d,o as n,c as p,q as E,j as i,D as a,d as s,s as l,S as o,b as r}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"全文检索引擎","description":"","frontmatter":{"title":"全文检索引擎","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/search-engine-index.md","filePath":"cs/search-engine-index.md","lastUpdated":1791413859000}'),A={name:"cs/search-engine-index.md"};function c(D,e,h,m,f,u){const t=d("Mermaid");return n(),p("div",null,[e[2]||(e[2]=E('<h1 id="全文检索引擎" tabindex="-1">全文检索引擎 <a class="header-anchor" href="#全文检索引擎" aria-label="Permalink to &quot;全文检索引擎&quot;">​</a></h1><div class="epigraph"><p>独立搜索引擎把倒排段、打分、分片做成集群：近实时可见靠刷新，不是 SQL 提交即搜。库内 GIN 是子集。</p><footer>—— 据 Lucene 架构；Manning IR；倒排课的集群落地</footer></div><p><a href="/cs/vector-db-ann">上一课</a>可与全文混合。本课专搜索引擎：Elasticsearch/Lucene 一族。缺口是相对库内全文：刷新间隔、副本分片、评分相关性、与主库 CDC 对齐。事务课的 D 在这里常是「近实时」，RPO 按刷新与 translog。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>文档进缓冲，refresh 成可搜段，search 多段归并，merge 后台——LSM 同构。缺口是 <strong>SQL 事务 vs 可搜</strong>：未 refresh 的文档搜不到，应用若以为提交即搜会错。CDC 从库到引擎是异步，读己之写要等 refresh 或搜主库。<span class="marginnote">「refresh」翻译过来就是：把内存里攒着的新文档封成一个只读小段，让它们从「写了但搜不到」变成「搜得到」。它约每秒一次，本质是在「可见快」和「段太碎要频繁合并」之间做取舍。</span></p><p>分片：文档 id 哈希， scatter 查询再合并打分——分布式 top-k。相关性：BM25 在引擎，SQL <code>ORDER BY</code> 不是同一回事。</p><p><span class="marginnote">Lucene 段与 translog。本课集群合同。库内倒排课已有 posting。向量可作为 Lucene 字段。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>索引模板、mapping（分析器）。查询 DSL。与关系：主键同步、死信重试。权限：字段级安全 vs 后课行级安全在库。</p><p>容量：倒排内存、doc values 列存给排序聚合——引擎内 HTAP 雏形。</p>',10)),(n(),i(o,null,{default:a(()=>[l(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20IDX%5B%22index%20%E7%BC%93%E5%86%B2%22%5D%20--%3E%20REF%5B%22refresh%20%E6%88%90%E6%AE%B5%22%5D%0A%20%20REF%20--%3E%20SCH%5B%22%E5%A4%9A%E6%AE%B5%E6%A3%80%E7%B4%A2%E6%89%93%E5%88%86%22%5D%0A%20%20REF%20--%3E%20MRG%5B%22merge%22%5D%0A%20%20DB%5B%22%E4%B8%BB%E5%BA%93%E6%8F%90%E4%BA%A4%22%5D%20--%3E%20CDC%5B%22%E5%BC%82%E6%AD%A5%E5%88%B0%E5%BC%95%E6%93%8E%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=r("h2",{id:"机制",tabindex:"-1"},[s("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=r("p",null,"一致性：副本等待可配，类似半同步。脑裂有选举。Jepsen 后课对搜索集群也测过丢失。优化：filter 上下文走位图缓存，query 上下文打分。",-1)),e[5]||(e[5]=r("p",null,"同一次查询里，两种上下文走的是完全不同的计算路径——过滤部分能命中缓存复用，打分部分必须逐文档算：",-1)),(n(),i(o,null,{default:a(()=>[l(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20Q%5B%22%E6%9F%A5%E8%AF%A2%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20S%7B%22%E6%8B%86%E5%88%86%E4%B8%8A%E4%B8%8B%E6%96%87%22%7D%0A%20%20S%20--%20%22filter%20%E5%AD%90%E5%8F%A5%22%20--%3E%20BM%5B%22%E4%BD%8D%E5%9B%BE%E5%8C%B9%E9%85%8D%E5%91%BD%E4%B8%AD%2F%E4%B8%8D%E5%91%BD%E4%B8%AD%22%5D%0A%20%20BM%20--%3E%20CA%5B%22%E6%9F%A5%E4%BD%8D%E5%9B%BE%E7%BC%93%E5%AD%98%22%5D%0A%20%20CA%20--%3E%20IT%5B%22%E5%A4%9A%E6%9D%A1%E4%BB%B6%E4%BD%8D%E5%9B%BE%E6%B1%82%E4%BA%A4%E9%9B%86%22%5D%0A%20%20S%20--%20%22query%20%E5%AD%90%E5%8F%A5%22%20--%3E%20SC%5B%22%E9%80%90%E6%96%87%E6%A1%A3%E7%AE%97%20BM25%20%E5%88%86%22%5D%0A%20%20IT%20--%3E%20TOP%5B%22%E6%8C%89%E7%9B%B8%E5%85%B3%E5%88%86%E6%8E%92%E5%BA%8F%E5%8F%96%20top-k%22%5D%0A%20%20SC%20--%3E%20TOP%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[s(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=E('<p>与 zone：段上的 doc 值 min/max 跳过。<span class="marginnote">数字实例：一亿文档、refresh 周期 1 秒，意味着主库提交后最坏要再等约 1 秒新文档才可搜——这就是「读己之写」时要么按 _id 直查（走实时变更记录，不等 refresh）、要么读主库的原因。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 SQLite 页。也不把搜索当唯一真相库——主库仍权威。湖仓分析另一路。</p><p>后课默认：全文集群近实时；提交即搜要等或走库。SQLite 架构：嵌入式整库一份文件，另一极端。</p><p>搜索引擎是特化执行器+倒排存储，不是 Selinger 的通用 SQL。<span class="marginnote">常见误区：初学者容易把所有条件都写进 query 上下文，以为「打分越全越准」——实际上纯过滤条件（状态=已发布、时间在某区间）放 filter 上下文既不算分还能吃位图缓存，同样的条件放 query 里就是白白重复计算。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>段+refresh+merge 近实时可搜；与 SQL 提交不同步除非等待。</li><li>分片 scatter 打分；CDC 对齐主库。</li><li>SQLite 架构下一课。</li><li>出处：Lucene；Manning IR；LSM 对照。</li></ul>',7))])}const C=B(A,[["render",c]]);export{g as __pageData,C as default};
